# November 16, 2026: more places round Albany that the Atlas did not have, mostly remains on public or preserve land.
# Facts come from the linked sources only: Wikipedia articles read through tools/wiki_raw.py, New York State Parks
# pages, the Mohawk Hudson Land Conservancy, the New England Lost Ski Areas Project, the Great Northern Catskills
# visitor site, and for the Hannacroix Creek Preserve a directory listing and two walkers' write-ups, as linked.
# Where a source is silent the text says so and conf is set; nothing here is filled in from memory.
# Ownership lines that say "public-land database" come from PAD-US (tools/pad.py) at the pin.
# Pins come from the article's coordinates or a named OpenStreetMap feature (tools/nom.py), as each pin note says.
from data_b import N
from data_ma import W
BATCH={'key':'albany2','label':'More around Albany','added':'2026-11-16 12:30'}
PARKS=lambda name,slug:['NYS Parks: '+name,'https://parks.ny.gov/visit/state-parks/'+slug]
PLACES=[
N('dickinson-hill-fire-tower','Dickinson Hill Fire Tower','Grafton','renss','landmark','standing',42.79376,-73.41403,'exact','view','walk','','1924–1972',
  'A steel lookout tower, a prefabricated kit from the Aermotor Corporation, put up in 1924 to watch for forest fires. It has not been staffed since 1972 and is the last fire tower left in Rensselaer County. It was listed on the National Register in 2011.',
  'The tower, a concrete water tank and the foundation of the observer\'s cabin.',
  'The last fire tower in the county.',
  'On Fire Tower Road. Grafton Lakes State Park land lies within half a mile, but the public-land database does not show the tower\'s own lot as park land, and the sources read do not say who looks after it or whether it may be climbed. The state park is open all year from 8 am to sunset and charges $8 a vehicle from Memorial Day weekend to Labor Day.',
  [W('Dickinson Hill Fire Tower'),PARKS('Grafton Lakes State Park','grafton-lakes-state-park')],conf='mixed'),
N('valley-paper-mill-chimney','Valley Paper Mill chimney','Alcove','albco','industry','ruins',42.47335,-73.92336,'exact','view','drive','burned','1844–1891',
  'A straw-pulp paper mill was built at Alcove in 1844. Fire destroyed it in 1891, and the site was levelled and filled. The mill\'s brick chimney was left: 9.5 feet square at the base, tapering, 110 feet tall.',
  'The chimney, standing alone, with an information board near it on County Road 111. Much of the buried mill site is said to be undisturbed since the fire.',
  'A 110-foot chimney with no mill.',
  'Look from County Road 111, where OpenStreetMap maps the information board. The public-land database lists Alcove Preservation Association land, open to the public, and Albany Water Board land, access not recorded, within 200 m; which one the chimney stands on was not confirmed.',
  [W('Valley Paper Mill Chimney and Site')],conf='mixed'),
N('croswell-parsons-paper-mill','Croswell-Parsons paper mill ruin','New Baltimore','hud','industry','ruins',42.45751,-73.79921,'area','public','hike','','',
  'Several paper mills worked along the Hannacroix Creek in the 19th century. The ruin of one, the Croswell-Parsons mill, was listed on the National Register in 1996 as an industrial ruin and archaeological site. The land is now the 113-acre Hannacroix Creek Preserve, bought by the Open Space Institute and managed by the New Baltimore Conservancy. The sources read give no dates for the mill.',
  'Stone walls and a foundation beside the creek on the Paper Mill Trail, and a waterfall on a side trail. A walker in 2013 wrote that only the mills\' interior stone walls remain.',
  'Paper-mill walls in the woods.',
  'Open Space Institute land, managed by the New Baltimore Conservancy and open to the public. Park on the west side of Route 144 just south of the Albany–Greene county line; a kiosk there has a trail map. The Paper Mill Trail is about 2 miles out and back. No motor vehicles.',
  [W('Croswell-Parsons Paper Mill Ruin'),['AARP local listing: Hannacroix Creek Preserve','https://local.aarp.org/place/hannacroix-creek-preserve-new-baltimore-ny.html'],['Walking Man 24/7: Hannacroix Creek Preserve (2013)','https://walkingman247.blogspot.com/2013/10/hannacroix-creek-preserve.html'],['P. McConnell: a walk at the preserve (2023)','https://pmcconnell.micro.blog/2023/01/16/spring-runnoff-in.html']],conf='mixed'),
N('five-combines-locks','Five Combines locks','Hudson Falls','wash','canal','standing',43.29677,-73.56922,'site','public','walk','canal','1832–early 1900s',
  'The Glens Falls Feeder Canal was dug from 1824 to carry Hudson River water from above Glens Falls to the highest level of the Champlain Canal. In 1832 it was widened and deepened for boats, and thirteen masonry locks were built to take them down the drop east of Sandy Hill, now Hudson Falls. Five of them stand one after another here as the Five Combines, lowering the water 55 feet. The Champlain Barge Canal ended boat traffic on the feeder in the early 1900s; it still carries water.',
  'The stepped flight of five lock chambers at Pine Street and Burgoyne Avenue, and the towpath trail. The article does not describe their condition.',
  'A staircase of five locks on a canal built to feed another canal.',
  'State canal land, open to the public. The Feeder Canal Heritage Trail follows the towpath; the Feeder Canal Alliance, formed in 1987, looks after the canal.',
  [W('Glens Falls Feeder Canal')],was='feeder-five-combines'),
N('peebles-island-earthworks','Peebles Island earthworks','Waterford','conf','fort','traces',42.782,-73.686,'area','public','walk','forts','1777',
  'In 1777, with a British army coming down from Canada, General Philip Schuyler chose Peebles Island for his last stand in front of Albany: the islands at the mouth of the Mohawk commanded the fords and suited cannon. General John Glover was put in charge of the island and its guns. The defenses were never tested. Horatio Gates replaced Schuyler and marched the army north to fight at Saratoga.',
  'Earthworks dating from the Revolutionary War; the sources read do not say where on the island they are. A converted factory complex on the island houses the state\'s historic preservation offices, and a visitors\' center tells the island\'s industrial history.',
  'The fort that was dug to save Albany and never fired a shot.',
  'Peebles Island State Park. Open all year, sunrise to sunset; walking trails all year; no bicycles on the trails. A vehicle fee may apply: see the park page.',
  [PARKS('Peebles Island State Park','peebles-island-state-park'),W('Peebles Island State Park')]),
N('stuyvesant-falls-mills','Stuyvesant Falls mill district','Stuyvesant Falls','hud','industry','standing',42.35639,-73.73417,'site','view','drive','','',
  'The hamlet of Stuyvesant Falls lived off two falls of the Kinderhook Creek. On the east bank stood a grist mill, a paper mill, a cotton mill and a woolen mill complex, now only sites, beside a hydroelectric plant that survives. On the west bank three 19th-century cotton mills still stand. The district, with an iron truss bridge put up in 1899, was listed on the National Register in 1976.',
  'The upper and lower falls and their mill dams, three cotton mills on the west bank, the hydroelectric plant, and the 1899 iron truss bridge.',
  '',
  'The mills and the power plant are not public: look from the roads. The public-land database shows a parcel of town land near the falls, with access not recorded.',
  [W('Stuyvesant Falls Mill District')]),
N('troy-gasholder','Troy Gasholder Building','Troy','troy','landmark','standing',42.72139,-73.69056,'exact','view','drive','','',
  'A brick house built to shelter a telescoping iron tank of coal gas; the tank\'s weight pushed the gas out through the city\'s mains. It was designed by Frederick A. Sabbaton, superintendent of the Troy Gas Light Company from 1862 to 1890. The company first supplied gas in 1848 and had the city to itself until 1875. Only ten or so gasholder houses of this kind are left. The article read does not give the year it was built.',
  'The brick gasholder house, a large round building on the aerial. The gas works themselves were two blocks north and are not described as surviving.',
  'One of about ten gasholder houses left.',
  'Ownership was not confirmed: treat it as private and look from the street.',
  [W('Troy Gas Light Company')],conf='mixed'),
N('hadley-bow-bridge','Hadley Bow Bridge','Hadley','adk','landmark','standing',43.31389,-73.845,'exact','public','drive','','1885',
  'An iron bridge carrying Corinth Road over the Sacandaga River just above where it meets the Hudson. The town board sought bids for it early in 1885. It is the only iron semi-deck lenticular truss left in New York, and of three known to have been built it is the only one standing. After it was listed on the National Register in 1977 it was closed to vehicles and later to walkers too, and the county thought of demolishing it. It was rebuilt with federal and state grants and reopened in 2006 with no load limit.',
  'Two spans of different lengths on fieldstone abutments and a pier, over a deep gorge. An interpretive panel stands near the bridge, and a railroad bridge crosses just upstream.',
  'The last bridge of its kind, saved after years shut.',
  'A public road, Saratoga County Route 1.',
  [W('Hadley Parabolic Bridge')]),
N('wolf-creek-falls-farm','Wolf Creek Falls Preserve farm remains','Knox','albco','town','traces',42.72353,-74.08502,'area','public','hike','','',
  'A hill farm gone back to woods. Its stone-walled sheep pasture, a stone quarry, barbed-wire fencing from later beef cattle and the cellar of a house are still to be found along the trails. The land was given to the Mohawk Hudson Land Conservancy in 2007.',
  'Stone walls, a small quarry, old fence wire and a cellar hole, with waterfalls along the creek. The conservancy does not say where on the trails each one is.',
  'A farm you can read in the woods: pasture walls, quarry, cellar.',
  'Mohawk Hudson Land Conservancy preserve, open to the public. Trails run on both sides of Bozenkill Road. The preserve surrounds two private homes, so stay on the marked trails. (The national public-land database lists this land as closed; the conservancy\'s own page invites visitors.)',
  [['Mohawk Hudson Land Conservancy: Wolf Creek Falls Preserve','https://mohawkhudson.org/preserves/wolf-creek-falls-preserve']],conf='mixed',th=[42.72142,-74.08555],thn='Trail kiosk on the red trail (OpenStreetMap)'),
N('petersburg-pass-ski-area','Petersburg Pass ski area','Petersburgh','renss','amuse','traces',42.72319,-73.27774,'area','public','hike','','1962–about 1980',
  'Two executives of the Sprague Electric Company opened a ski area at the top of the pass on Route 2 in 1962, with a Poma double chairlift and three trails. It was sold in 1967, closed in 1969 and sat empty for three years; the first base lodge probably burned about 1970. Mark Raimer bought it in 1972 and reopened it, renamed Taconic Trails and later renamed again. Money trouble closed it around 1980, and the lifts stayed on the hill until 1982 or 1983.',
  'The source does not say what is left on the ground. The slopes were on the south side of Route 2 at the state line, and the Taconic Crest Trail crosses the road at the pass.',
  'A ski area that closed twice, on a ridge you can still walk.',
  'Taconic Ridge State Forest (NYS DEC), open to the public. The pin is the Petersburg Pass parking lot on Route 2, as OpenStreetMap maps it.',
  [['New England Lost Ski Areas Project: Petersburg Pass','https://www.nelsap.org/ny/petersburg.html']],conf='mixed'),
N('starks-knob','Stark\'s Knob','Schuylerville','sar','landmark','standing',43.11827,-73.58771,'site','public','walk','','',
  'A knob of pillow lava that erupted on a shallow sea floor some 460 to 440 million years ago; early writers took it for a volcano. It is named for General John Stark of New Hampshire, who cut off the retreat of Burgoyne\'s army here in the Saratoga campaign. The property was deeded to the state in 1916, partly to keep the rock from being mined for road building. After years of neglect the state acted to curb vandalism and keep up the trails, and in 2005 the site joined the master plan for Hudson Crossing Park.',
  'The basalt outcrop and its trails.',
  '',
  'State land. The sources read give no hours or parking details, and the public-land database has no entry at the pin: check before going.',
  [W("Stark's Knob")],conf='mixed'),
N('natural-bridge-quarry','Natural Bridge marble quarry','North Adams','berk','industry','traces',42.70742,-73.09278,'site','public','walk','','1810–1947',
  'Marble was quarried here from 1810 to 1947, beside a natural bridge of white marble cut by Hudson Brook. From 1950 to 1983 the place was a private tourist attraction, and in 1985 it became a state park. Nathaniel Hawthorne came to see the arch and the quarry in 1838.',
  'The old quarry, a dam built of white marble, the brook\'s marble channel and the natural bridge itself, on short woodland walks.',
  'A quarry, a marble dam and a natural bridge in one small park.',
  'Natural Bridge State Park, Massachusetts. The article read does not give its season, hours or parking fee: check before going.',
  [W('Natural Bridge State Park (Massachusetts)')]),
N('cohotate-ice-house','Cohotate Preserve ice house foundation','Athens','hud','industry','traces',42.24572,-73.84095,'area','public','walk','','',
  'The remains of an old ice house foundation sit at the edge of the Hudson in this preserve, on the west bank just north of the Rip Van Winkle Bridge. The source gives no name or dates for the ice house.',
  'The foundation at the water, now a picnic spot, reached by trails with observation platforms.',
  '',
  'Greene County land, open all year. Columbia-Greene Community College runs an environmental field station on the preserve.',
  [['Great Northern Catskills: Cohotate Preserve','https://www.greatnortherncatskills.com/outdoors/cohotate-preserve']],conf='mixed'),
N('hadley-mountain-fire-tower','Hadley Mountain fire tower','Hadley','adk','landmark','standing',43.37698,-73.97078,'exact','public','hike','','1917 or 1920',
  'A steel fire lookout on the summit of Hadley Mountain, a prefabricated tower from the Aermotor Corporation and one of the first ten the state bought to guard the Adirondack Forest Preserve against fire. The dates do not agree: the article says it was built in 1917, and a plaque at the foot of the trail says a wooden tower went up in 1916 and the present steel one in 1920. It was listed on the National Register in 2001.',
  'The tower on the summit. A steward may be there in summer to answer hikers\' questions.',
  'One of the state\'s first ten steel fire towers.',
  'State forest preserve: the public-land database puts the summit in the Wilcox Lake Wild Forest (NYS DEC), open to the public. A foot trail leads up from a trailhead with a plaque; the article read does not name the road or give the distance.',
  [W('Hadley Mountain Fire Observation Station')],conf='mixed'),
N('kane-mountain-fire-tower','Kane Mountain fire tower','Caroga','adk','landmark','standing',43.18089,-74.51549,'site','public','hike','','1925',
  'A steel-frame Aermotor lookout tower put up on Kane Mountain in 1925 to watch over the Adirondack Forest Preserve, with an observer\'s cabin added about 1960. The station was listed on the National Register in 2001.',
  'The tower and the observer\'s cabin on the 2,200-foot summit.',
  'Half a mile of climbing to a 1925 fire tower.',
  'Three foot trails reach the summit. The main one, from Green Lake Road, is half a mile and climbs 600 feet. A second, from Schoolhouse Road, is shorter but steeper and rockier. A third starts from the Green Lake Road trailhead or the Pine Lake Campground. The public-land database puts the summit in the Shaker Mountain Wild Forest (NYS DEC), open to the public. OpenStreetMap labels one path near the summit "closed trail", so go by the signs on the ground.',
  [W('Kane Mountain Fire Observation Station')]),
N('samuel-sweet-canal-store','Samuel Sweet Canal Store','Amsterdam','mohawk','canal','standing',42.93444,-74.19833,'site','view','drive','canal','about 1847',
  'A three-story store of rough-cut pale grey limestone, about 30 feet by 70, built around 1847 at 65 Bridge Street to serve boats on the Erie Canal. It was both a shop and a forwarding warehouse for goods sent across the Mohawk. It was listed on the National Register in 1989.',
  'The limestone building at 65 Bridge Street.',
  '',
  'Present use and ownership were not confirmed: look from the street.',
  [W('Samuel Sweet Canal Store')],conf='mixed'),
N('furnace-grove-bennington','Furnace Grove iron furnaces','Bennington','vt','industry','ruins',42.885,-73.15667,'site','view','drive','','1805–1830s',
  'An iron furnace was set up here in 1805 by the owners of another furnace nearby whose ore had run out. Output peaked in the 1830s, and afterwards the works became a gentleman\'s farm. The ruins of two furnaces survive; a third was pulled apart and its stone built into the entrance gates. The remains of the canal and holding pond that fed the works are also there, with a stretch of the Bennington and Glastenbury Railroad grade. The district was listed on the National Register in 1997.',
  'Two furnace ruins, the gates built from a third, and the houses of the later farm, on the north side of Vermont Route 9 east of the town center.',
  'Iron furnaces of 1805 that ended up as garden gates.',
  'Private: the old company store is a private house and the article describes no public access. Look from Route 9 only.',
  [W('Furnace Grove Historic District')]),
]
